import React from 'react';
import { Box, Button, Typography } from '@mui/material';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import CheckIcon from '@mui/icons-material/Check';
import { UpiLogo } from '@/components/ui/SvgIcons';

interface UpiAddressBoxProps {
    address: string;
    label?: string;
}

/**
 * Shows a UPI address as prominent monospace text with a separate "Copy UPI" button, used
 * instead of a "Donate Here" link when an event's donation link holds a UPI id rather than a URL.
 */
export const UpiAddressBox: React.FC<UpiAddressBoxProps> = ({ address, label = 'UPI Address' }) => {
    const [copied, setCopied] = React.useState(false);
    const resetTimerRef = React.useRef<ReturnType<typeof setTimeout> | null>(null);

    React.useEffect(() => () => {
        if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
    }, []);

    const handleCopy = async (e: React.MouseEvent) => {
        e.stopPropagation();
        try {
            await navigator.clipboard.writeText(address);
            setCopied(true);
            if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
            resetTimerRef.current = setTimeout(() => setCopied(false), 2000);
        } catch {
            setCopied(false);
        }
    };

    return (
        <Box sx={{ mt: 0.5 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, mb: 0.5 }}>
                <UpiLogo height={14} aria-label="UPI" role="img" style={{ display: 'block' }} />
                <Typography variant="body2" component="span" sx={{ fontWeight: 600, color: 'primary.main' }}>
                    {label}:
                </Typography>
            </Box>
            <Box
                sx={{
                    display: 'inline-block',
                    maxWidth: '100%',
                    px: 1.25,
                    py: 0.5,
                    borderRadius: 1,
                    border: '1px dashed',
                    borderColor: 'secondary.main',
                    backgroundColor: 'action.hover',
                }}
            >
                <Typography
                    component="span"
                    sx={{
                        fontFamily: 'Consolas, "Courier New", monospace',
                        fontSize: '1rem',
                        fontWeight: 700,
                        lineHeight: 1.4,
                        letterSpacing: '0.01em',
                        wordBreak: 'break-all',
                        color: 'secondary.main',
                        userSelect: 'all',
                    }}
                >
                    {address}
                </Typography>
            </Box>
            <Box>
                <Button
                    size="small"
                    variant="outlined"
                    color="secondary"
                    onClick={handleCopy}
                    startIcon={copied ? <CheckIcon fontSize="small" /> : <ContentCopyIcon fontSize="small" />}
                    sx={{
                        mt: 1,
                        textTransform: 'none',
                        // globals.css colours every `button > span` and `button > span > svg` from its
                        // own palette, which would grey out (or hide) the icon on this outlined button.
                        '& .MuiButton-startIcon': { color: 'inherit' },
                        '& .MuiButton-startIcon svg': { color: 'inherit', fill: 'currentColor' },
                    }}
                >
                    {copied ? 'Copied' : 'Copy UPI'}
                </Button>
            </Box>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.75 }}>
                Copy the UPI address, paste it into your preferred UPI app, and complete the payment there.
            </Typography>
        </Box>
    );
};
